import React from 'react';
import { Staff } from '../types/game';

interface StaffCardProps {
  staff: Staff;
}

const StaffCard: React.FC<StaffCardProps> = ({ staff }) => {
  const isEmployeeOfMonth = staff.awards?.includes('Employee of the Month');

  return (
    <div className={`bg-hitman-gray p-4 rounded-lg shadow-lg border transition-all ${
      isEmployeeOfMonth ? 'border-yellow-500 shadow-yellow-900/20' : 'border-gray-700 hover:border-hitman-red'
    }`}>
      <div className="flex justify-between items-start mb-2">
        <div className="flex gap-3">
          {/* Silhouette Passport Photo */}
          <div className="w-12 h-12 bg-black rounded border border-gray-600 flex items-center justify-center overflow-hidden shrink-0">
            <svg className="w-10 h-10 text-gray-700 mt-2" fill="currentColor" viewBox="0 0 24 24">
              <path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z" />
            </svg>
          </div>
          <div>
            <h3 className="text-xl font-bold text-white flex items-center gap-2">
              {staff.name}
              {isEmployeeOfMonth && (
                <span title="Employee of the Month" className="text-yellow-500 text-lg">★</span>
              )}
            </h3>
            <span className="text-[10px] uppercase bg-hitman-red px-2 py-0.5 rounded text-white font-semibold">
              {staff.type}
            </span>
          </div>
        </div>
        <div className="text-right">
          <p className="text-sm text-gray-400">Age: {staff.age}</p>
          <p className="text-sm text-green-500 font-mono">${staff.salary}/day</p>
        </div>
      </div>

      {staff.previousJob && (
        <div className="mt-2 text-[10px] text-gray-400 italic">
          Prev: {staff.previousJob}
        </div>
      )}

      {staff.quirk && (
        <div className="mt-1 text-[10px] text-hitman-red font-bold uppercase tracking-tighter">
          QUIRK: {staff.quirk}
        </div>
      )}

      <div className="grid grid-cols-2 gap-2 mt-4">
        {Object.entries(staff.skills).map(([skill, value]) => (
          <div key={skill} className="flex flex-col">
            <span className="text-[10px] uppercase text-gray-500">{skill}</span>
            <div className="w-full bg-black h-1.5 rounded-full mt-1">
              <div
                className="bg-hitman-red h-full rounded-full"
                style={{ width: `${(value / 5) * 100}%` }}
              />
            </div>
          </div>
        ))}
      </div>

      <div className="mt-4 flex justify-between items-center">
        <span className={`text-xs px-2 py-1 rounded ${
          staff.status === 'IDLE' ? 'bg-green-900 text-green-300' :
          staff.status === 'ON_MISSION' ? 'bg-blue-900 text-blue-300' : 'bg-red-900 text-red-300'
        }`}>
          {staff.status}
        </span>
        <button className="text-xs text-gray-400 hover:text-white underline">
          View Details
        </button>
      </div>
    </div>
  );
};

export default StaffCard;
